/**
 * Seven endings, gated three ways: by an ally, by a choice, or by the clock.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "endings".
 */
export interface Ending {
  id: number;
  title: string;
  /**
   * URL segment. Auto-filled from the title. Changing it breaks existing links.
   */
  slug: string;
  /**
   * Optional. A screenshot or piece of art for this record. Until one is set, the site falls back to its own icon, so a missing image never leaves a hole.
   */
  image?: (number | null) | Media;
  gate: 'ally' | 'choice' | 'clock';
  /**
   * The ally whose questline gates this ending.
   */
  ally?: (number | null) | Character;
  /**
   * Everything that must be completed to reach this ending. The checker walks prereqs from here, so listing only the questline itself is enough.
   */
  requiredQuests?: (number | Quest)[] | null;
  /**
   * True for "Time Runs Out" — reached by missing the deadline, not by choosing.
   */
  isFailure?: boolean | null;
  /**
   * True for endings that close the run early, before the Brencis confrontation.
   */
  isEarlyExit?: boolean | null;
  /**
   * What the player must DO. Not a spoiler — shown openly, because this is what someone mid-run came for.
   */
  howToGet?: string | null;
  /**
   * What actually HAPPENS in this ending. This is the spoiler, and it stays covered until the reader clicks to reveal it. Keep the two separate — it is the distinction every other site fails to make.
   */
  outcome?: string | null;
  /**
   * Shown to readers as a badge. Be honest — it is the whole point of this site.
   */
  confidence: 'high' | 'medium' | 'low';
  /**
   * One or two sentences. Used on cards, in search results and as the page lede.
   */
  summary: string;
  /**
   * The main article. Original prose only — never paste from another site.
   */
  body?: {
    root: {
      type: string;
      children: {
        type: any;
        version: number;
        [k: string]: unknown;
      }[];
      direction: ('ltr' | 'rtl') | null;
      format: 'left' | 'start' | 'center' | 'right' | 'end' | 'justify' | '';
      indent: number;
      version: number;
    };
    [k: string]: unknown;
  } | null;
  /**
   * Cite every figure. Two independent sources before marking confidence high.
   */
  sources?:
    | {
        title: string;
        url: string;
        retrieved?: string | null;
        id?: string | null;
      }[]
    | null;
  /**
   * Leave blank to derive from the title and summary.
   */
  seo?: {
    /**
     * Under ~60 characters. Overrides the <title> tag.
     */
    title?: string | null;
    /**
     * Under ~155 characters. Overrides the meta description.
     */
    description?: string | null;
    /**
     * Hide this page from search engines.
     */
    noindex?: boolean | null;
  };
  /**
   * Which wiki this belongs to. Moving a record between games changes its URL.
   */
  game: number | Game;
  updatedAt: string;
  createdAt: string;
}
